export async function initiateOwnershipHandover(actor: Actor, orgId: OrgId, toUserId: UserId): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:delete", { action: "org:delete", resourceKind: "organization", allowed: false, reason: "denied_by_role" });
  }
  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") throw new NotFoundError("Member", toUserId);
  if (toUserId === actor.userId) throw new OwnershipHandoverError("self");
  const now = toIsoTimestamp(new Date());
  await handoverRepo.expireLapsed(orgId, now);
  if (await handoverRepo.findCurrentPending(orgId)) throw new OwnershipHandoverError("pending_exists");
  const offer = await handoverRepo.create(orgId, actor.userId, toUserId);
  const { notify } = await import("./notification-service");
  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Workspace ownership offered",
    body: `${actor.userId} offered you ownership of this workspace`,
    href: "/settings/members",
    actorId: actor.userId,
  });
  return offer;
}

export async function getPendingOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  await requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const now = toIsoTimestamp(new Date());
  await handoverRepo.expireLapsed(orgId, now);
  return handoverRepo.findPending(orgId, now);
}

async function resolveOffer(actor: Actor, orgId: OrgId, outcome: "accepted" | "declined" | "canceled"): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  await requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const now = toIsoTimestamp(new Date());
  const pending = await handoverRepo.findCurrentPending(orgId);
  if (!pending) throw new OwnershipHandoverError("nothing_pending");
  if (pending.expiresAt < now) {
    await handoverRepo.expireLapsed(orgId, now);
    if (outcome === "canceled") throw new OwnershipHandoverError("nothing_pending");
    if (actor.userId !== pending.toUserId) throw new OwnershipHandoverError("nothing_pending");
    throw new OwnershipHandoverError("expired");
  }
  if (outcome === "canceled") {
    if (actor.userId !== pending.fromUserId) throw new PermissionDeniedError("org:update", { action: "org:update", resourceKind: "organization", allowed: false, reason: "denied_by_role" });
  } else if (actor.userId !== pending.toUserId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return handoverRepo.resolve(pending.id, orgId, outcome, now);
}

export async function declineOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  return resolveOffer(actor, orgId, "declined");
}

export async function cancelOwnershipHandover(actor: Actor, orgId: OrgId): Promise<OwnershipHandover> {
  return resolveOffer(actor, orgId, "canceled");
}

export async function acceptOwnershipHandover(actor: Actor, orgId: OrgId): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const now = toIsoTimestamp(new Date());
  const pending = await handoverRepo.findCurrentPending(orgId);
  if (!pending) throw new OwnershipHandoverError("nothing_pending");
  if (pending.expiresAt < now) {
    await handoverRepo.expireLapsed(orgId, now);
    if (actor.userId !== pending.toUserId) throw new OwnershipHandoverError("nothing_pending");
    throw new OwnershipHandoverError("expired");
  }
  if (actor.userId !== pending.toUserId) throw new OwnershipHandoverError("nothing_pending");
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  const fromMember = await memberRepo.findMember(orgId, pending.fromUserId);
  const toMember = await memberRepo.findMember(orgId, pending.toUserId);
  if (!fromMember || fromMember.status !== "active" || !toMember || toMember.status !== "active") {
    await handoverRepo.resolve(pending.id, orgId, "canceled", now);
    throw new OwnershipHandoverError("nothing_pending");
  }
  await handoverRepo.resolve(pending.id, orgId, "accepted", now);
  const updatedOrg = await orgRepo.transferOwner(orgId, pending.fromUserId, pending.toUserId);
  if (toMember.role !== "owner") {
    await memberRepo.updateMemberRole(orgId, toMember.id, "owner");
    await emit("member.role_changed", { ...actorEnvelope(actor), memberId: toMember.id, from: toMember.role, to: "owner" });
  }
  if (fromMember.role === "owner") {
    await memberRepo.updateMemberRole(orgId, fromMember.id, "admin");
    await emit("member.role_changed", { ...actorEnvelope(actor), memberId: fromMember.id, from: "owner", to: "admin" });
  }
  await emit("organization.ownership_transferred", { ...actorEnvelope(actor), fromUserId: pending.fromUserId, toUserId: pending.toUserId });
  return updatedOrg;
}
