import { and, eq, gte, lt, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { brandId, brandStamp, brandStampOrNull } from "./_mappers";
import type { OrgId, UserId } from "@/types/common";
import type { OwnershipHandover, OwnershipHandoverStatus } from "@/types/organization";

function map(row: typeof ownershipHandovers.$inferSelect): OwnershipHandover {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    fromUserId: brandId<UserId>(row.fromUserId),
    toUserId: brandId<UserId>(row.toUserId),
    status: row.status,
    expiresAt: brandStamp(row.expiresAt),
    createdAt: brandStamp(row.createdAt),
    resolvedAt: brandStampOrNull(row.resolvedAt),
  };
}

export async function findPending(orgId: OrgId, now: string): Promise<OwnershipHandover | null> {
  const row = getDb().select().from(ownershipHandovers).where(and(
    eq(ownershipHandovers.orgId, orgId),
    eq(ownershipHandovers.status, "pending"),
    gte(ownershipHandovers.expiresAt, now),
  )).get();
  return row ? map(row) : null;
}

export async function findCurrentPending(orgId: OrgId): Promise<OwnershipHandover | null> {
  const row = getDb().select().from(ownershipHandovers).where(and(
    eq(ownershipHandovers.orgId, orgId),
    eq(ownershipHandovers.status, "pending"),
  )).get();
  return row ? map(row) : null;
}

export async function expireLapsed(orgId: OrgId, now: string): Promise<void> {
  getDb().update(ownershipHandovers).set({ status: "expired", resolvedAt: now })
    .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"), lt(ownershipHandovers.expiresAt, now))).run();
}

export async function create(orgId: OrgId, fromUserId: UserId, toUserId: UserId, nowDate = new Date()): Promise<OwnershipHandover> {
  const createdAt = toIsoTimestamp(nowDate);
  const expiresAt = toIsoTimestamp(new Date(nowDate.getTime() + 7 * 24 * 60 * 60 * 1000));
  const row = getDb().insert(ownershipHandovers).values({
    id: newId(), orgId, fromUserId, toUserId, status: "pending", createdAt, expiresAt, resolvedAt: null,
  }).returning().get();
  return map(row);
}

export async function resolve(id: string, orgId: OrgId, status: Exclude<OwnershipHandoverStatus, "pending">, at: string): Promise<OwnershipHandover> {
  const row = getDb().update(ownershipHandovers).set({ status, resolvedAt: at })
    .where(and(eq(ownershipHandovers.id, id), eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending")))
    .returning().get();
  if (!row) throw new Error("Ownership handover was concurrently resolved");
  return map(row);
}

export async function cancelForMember(orgId: OrgId, userId: UserId, at: string): Promise<void> {
  getDb().update(ownershipHandovers).set({ status: "canceled", resolvedAt: at })
    .where(and(eq(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.status, "pending"),
      or(eq(ownershipHandovers.fromUserId, userId), eq(ownershipHandovers.toUserId, userId)))).run();
}
